pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address user) public {
        // Restrict to reasonable amounts and valid user to keep the test wide but within gas limits
        vm.assume(user != address(0));
        vm.assume(user != address(c));
        depositAmount = bound(depositAmount, 1, 1000 ether);
        withdrawAmount = bound(withdrawAmount, 1, 1000 ether);
        vm.assume(depositAmount >= withdrawAmount);

        // Setup: deal and deposit
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.deposit{value: depositAmount}();

        // Perform the withdrawal
        vm.prank(user);
        c.withdraw(withdrawAmount);

        // Compute total balance stored in the mapping
        uint256 totalStored = c.balances(user);

        // The contract balance should equal the total balances recorded
        uint256 contractBalance = address(c).balance;

        // Invariant: sum of all stored balances == contract ETH balance
        // Since only one user deposited and withdrew, the contract balance must equal that user's recorded balance
        assertTrue(contractBalance == totalStored);
    }
}

